// ─── File: ExistsDemo.java ───
// Demonstrates EXISTS, NOT EXISTS, and the NOT IN + NULL trap.
package com.bank.exists;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ExistsDemo {
    private static final Logger log = Logger.getLogger(ExistsDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BankRepository repo = new BankRepository();
        ExistsService service = new ExistsService(repo);

        log.info("=== EXISTS: accounts with at least one txn ===");
        service.accountsWithTxn().forEach(id -> log.info("has txn: " + id));

        log.info("=== NOT EXISTS: accounts with no txn (safe anti-join) ===");
        service.accountsWithoutTxn().forEach(id -> log.info("no txn: " + id));

        log.info("=== NOT IN with NULL in set: returns NOTHING (the trap) ===");
        List<String> notIn = service.accountsWithoutTxnUsingNotIn();
        if (notIn.isEmpty())
            log.severe("NOT IN returned 0 rows because the txns set contains a NULL!");
    }
}

// ─── Would be in model/Account.java ───
class Account {
    final String accountId, holderName;
    Account(String id, String name) { this.accountId = id; this.holderName = name; }
}

// ─── Would be in model/Txn.java ───
class Txn {
    final String txnId, accountId; final BigDecimal amount; // accountId may be null
    Txn(String id, String acct, BigDecimal amt) {
        this.txnId = id; this.accountId = acct; this.amount = amt;
    }
}

// ─── Would be in repository/BankRepository.java ───
class BankRepository {
    List<Account> accounts() {
        return List.of(new Account("SAV2001", "Rajesh Kumar"),
                       new Account("CUR3001", "Priya Sharma"));
    }
    List<Txn> txns() {
        return List.of(
            new Txn("TX1", "SAV2001", new BigDecimal("40000")),
            new Txn("TX2", null,      new BigDecimal("99999"))); // NULL account_id
    }
}

// ─── Would be in service/ExistsService.java ───
class ExistsService {
    private final BankRepository repo;
    ExistsService(BankRepository repo) { this.repo = repo; }

    // EXISTS: short-circuits on first matching txn (anyMatch stops early).
    List<String> accountsWithTxn() {
        return repo.accounts().stream()
            .filter(a -> repo.txns().stream()
                .anyMatch(t -> a.accountId.equals(t.accountId)))
            .map(a -> a.accountId).toList();
    }

    // NOT EXISTS: safe anti-join, unaffected by NULL account ids.
    List<String> accountsWithoutTxn() {
        return repo.accounts().stream()
            .filter(a -> repo.txns().stream()
                .noneMatch(t -> a.accountId.equals(t.accountId)))
            .map(a -> a.accountId).toList();
    }

    // NOT IN simulation: if the set contains a NULL, SQL returns NOTHING.
    List<String> accountsWithoutTxnUsingNotIn() {
        List<String> set = repo.txns().stream().map(t -> t.accountId).toList();
        boolean setHasNull = set.stream().anyMatch(Objects::isNull);
        if (setHasNull) return List.of(); // mirrors SQL NOT IN + NULL => empty
        return repo.accounts().stream()
            .filter(a -> !set.contains(a.accountId))
            .map(a -> a.accountId).toList();
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
